import numpy as np
from collections import deque
def comps(g,color):
    g=np.array(g); seen=np.zeros(g.shape,bool); out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j]==color and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=1; c=[]
                while q:
                    a,b=q.popleft(); c.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<g.shape[0] and 0<=y<g.shape[1] and g[x,y]==color and not seen[x,y]:
                            seen[x,y]=1; q.append((x,y))
                out.append(c)
    return out
